css:
.lsd-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsd-root,.lsd-root *,.lsd-root *::before,.lsd-root *::after{box-sizing:border-box}
.lsd-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsd-root img{display:block;border:0;max-width:none}
.lsd-root [hidden]{display:none!important}
.lsd-root .n12_470{background-color:var(--wa-point, #193058);align-content:stretch;display:flex;gap:7px;height:25px;align-items:center;padding-left:7px;padding-right:4px;position:relative;border-radius:2px;flex-shrink:0;width:98px;border-style:solid;border-color:var(--wa-point, #6697c4);border-width:1px}
.lsd-root .n12_390{align-content:stretch;display:flex;gap:3px;align-items:center;position:relative;flex-shrink:0;width:34px}
.lsd-root .n12_391{position:relative;flex-shrink:0;width:12px;height:12px}
.lsd-root .x11{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsd-root .n12_392{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:normal;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #b3b4c1);font-size:12px;white-space:nowrap}
.lsd-root .n12_393{background-color:var(--wa-bg, #001227);align-content:stretch;display:flex;flex:1 0 0;height:19px;align-items:center;justify-content:flex-end;min-width:1px;padding-right:4px;position:relative;border-style:solid;border-color:var(--wa-point, #305c84);border-width:1px;filter:drop-shadow(2px 2px 2px rgba(0,0,0,0.25))}
.lsd-root .n12_394{word-break:break-word;font-weight:"Pretendard:Medium";line-height:normal;font-style:normal;position:relative;flex-shrink:0;font-size:16px;text-align:right;white-space:nowrap;color:var(--wa-danger, #f68989)}
.lsd-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsd-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsd-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsd-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsd-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsd-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsd-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsd-root[data-theme="light"] .n12_470{background-color:var(--wa-surface, #bac5d8);border-color:var(--wa-point, #7ca0c0)}
.lsd-root[data-theme="light"] .n12_392{color:var(--wa-text-sub, #454950)}
